//! P20 R124 "ANIMSND everywhere": route variants used by p17_chains when P17_ANIMSND=1 (the anim callback sound table
//! of game.exe, runtime_j2 `Subsystems.anim_sound`). Kept in this file (not in routes_epN.rs) so the episode lanes'
//! default routes do not conflict. EP2's variants live in routes_ep2.rs (EP2_*_ANIMSND, EP2_L01A_REAL).

/// ANIMSND steps for a chain level (None = the default EPn_ROUTE steps work under ANIMSND too).
pub fn variant(lvl: &str) -> Option<&'static str> {
    match lvl {
        "EP3/L01" => Some(EP3_L01_ANIMSND),
        "EP3/L05" => Some(EP3_L05_ANIMSND),
        "EP4/L02A" => Some(EP4_L02A_ANIMSND),
        "EP4/L04" => Some(EP4_L04_ANIMSND),
        "EP6/L03" => Some(EP6_L03_ANIMSND),
        "EP6/L04A" => Some(EP6_L04A_ANIMSND),
        "EP6/L04B" => Some(EP6_L04B_ANIMSND),
        "EP6/L05" => Some(EP6_L05_ANIMSND),
        "EP6/L05B" => Some(EP6_L05B_ANIMSND),
        _ => None,
    }
}

